function normalizePack(raw,name){let data=raw.data||raw;let elements=data.elements;if(data.type!=='FeatureCollection'&&!Array.isArray(elements))throw Error('Gunakan Overpass JSON, GeoJSON FeatureCollection, atau ekspor peta Sotrack.');if(elements?.length>200000||data.features?.length>100000)throw Error('Peta terlalu besar. Batas 200.000 elemen / 100.000 fitur.');if(elements){for(const e of elements)if(e.type==='node'&&(!Number.isFinite(e.lat)||!Number.isFinite(e.lon)||Math.abs(e.lat)>90||Math.abs(e.lon)>180))throw Error('Koordinat peta tidak valid');}const p={id:uid(),name:String(raw.name||name).slice(0,100),data,bounds:raw.bounds,created:Date.now(),attribution:raw.attribution||'© OpenStreetMap contributors / sumber file impor'};p.features=packFeatures(p);const coords=[];for(const f of p.features){const g=f.geometry;if(!g)continue;const visit=c=>{if(Array.isArray(c)&&typeof c[0]==='number'){if(!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90)throw Error('Koordinat GeoJSON tidak valid');coords.push(c);}else if(Array.isArray(c))for(const child of c)visit(child);};visit(g.coordinates);}if(!coords.length)throw Error('Tidak ada geometri jalan/peta dalam file.');if(!p.bounds){let minLat=90,minLon=180,maxLat=-90,maxLon=-180;for(const c of coords){minLat=Math.min(minLat,c[1]);maxLat=Math.max(maxLat,c[1]);minLon=Math.min(minLon,c[0]);maxLon=Math.max(maxLon,c[0]);}p.bounds=[minLat,minLon,maxLat,maxLon];}return p;}
$('#downloadMap').onclick=async()=>{const b=$('#downloadMap');if(!navigator.onLine){toast('Hubungkan internet untuk menyimpan area baru.');return;}const recent=packs.find(p=>(p.areaKm||4)>=Number($('#mapArea').value)&&p.center&&distance(p.center,center)<500&&Date.now()-p.created<86400000);if(recent){toast('Area ini sudah tersimpan. Gunakan peta offline yang ada.');return;}b.disabled=true;b.textContent='Mengunduh jalan…';$('#downloadStatus').textContent='Mengambil data jalan di pusat peta. Bisa memerlukan 30–60 detik.';const ctrl=new AbortController(),timeout=setTimeout(()=>ctrl.abort(),600000);downloadController=ctrl;$('#cancelMap').hidden=false;try{const lat=center.lat,lon=center.lon,km=Number($('#mapArea').value),bbox=boundsFor(center,km);const data=await requestRoads(bbox,{endpoint:window.sotrack.services.overpass,signal:ctrl.signal,onProgress:p=>$('#downloadStatus').textContent=`Mengambil jalan bagian ${p.done+1>p.total?p.total:p.done+1}/${p.total}. Area dibagi kecil agar permintaan lebih ringan.`});const pack=normalizePack({data,bounds:bbox,name:$('#mapAreaName').value.trim()||'Area '+lat.toFixed(3)+', '+lon.toFixed(3)+' · '+km+' km'},'Area offline');pack.center={lat,lon};pack.areaKm=km;const next=[pack,...packs];await commit([['packs',next]]);packs=next;$('#downloadStatus').textContent=`Tersimpan: ${pack.features.length} jalur. App siap menampilkan area ini offline.`;renderPacks();drawMap();storageInfo();toast('Peta jalan offline tersimpan.');}catch(e){$('#downloadStatus').textContent=e.name==='AbortError'?'Unduhan dibatalkan atau server terlalu lama merespons. Coba lagi nanti atau impor peta JSON.':e.message;toast($('#downloadStatus').textContent);}finally{clearTimeout(timeout);downloadController=null;$('#cancelMap').hidden=true;b.disabled=false;b.textContent='↓ Simpan area pusat peta';}};
