function renderHistory(){$('#totalRides').textContent=rides.length;$('#totalDistance').innerHTML=fmt(rides.reduce((s,r)=>s+r.distance,0)/1000)+' <em>km</em>';$('#totalTime').innerHTML=fmt(rides.reduce((s,r)=>s+r.elapsed,0)/3600000)+' <em>jam</em>';$('#totalAscent').innerHTML=Math.round(rides.reduce((s,r)=>s+r.ascent,0))+' <em>m</em>';const q=$('#historySearch').value.toLowerCase(),from=$('#historyFrom').value,to=$('#historyTo').value;const date=r=>new Date(r.start).toLocaleDateString('sv-SE');const list=rides.filter(r=>r.name.toLowerCase().includes(q)&&(!from||date(r)>=from)&&(!to||date(r)<=to));$('#historyList').innerHTML=list.length?list.map(r=>`<div class="listcard"><div><b>${esc(r.name)}</b><small>${new Date(r.start).toLocaleString('id-ID')} · ${fmt(r.distance/1000,2)} km · ${clock(r.elapsed)} · ${fmt(r.elapsed?r.distance/r.elapsed*3600:0)} km/j</small></div><div class="listactions"><button class="outline" data-detail="${r.id}">Detail</button><button class="outline" data-export="${r.id}">Unduh GPX ↓</button><button class="textbtn" data-delete="${r.id}">Hapus</button></div></div>`).join(''):'<div class="empty"><b>Your story starts here.</b>Belum ada aktivitas untuk periode ini.</div>';$$('[data-detail]').forEach(b=>b.onclick=()=>showDetail(rides.find(r=>r.id===b.dataset.detail)));$$('[data-export]').forEach(b=>b.onclick=()=>exportRide(rides.find(r=>r.id===b.dataset.export)));$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Hapus aktivitas ini? Pastikan sudah diekspor jika masih diperlukan.'))return;const next=rides.filter(r=>r.id!==b.dataset.delete);try{await commit([['rides',next]]);rides=next;$('#rideDetail').hidden=true;renderHistory();}catch(e){saveFailure(e);}});}
for(const sel of ['#historySearch','#historyFrom','#historyTo'])$(sel).oninput=renderHistory;
function exportRide(r){download(activityFilename(r,'gpx'),gpx(r),'application/gpx+xml');toast('Rekaman GPX diunduh.');}
function showDetail(r){const hrs=r.hrSamples?.map(s=>s.hr)||r.points.map(p=>p.hr).filter(Boolean),avg=hrs.length?Math.round(hrs.reduce((s,v)=>s+v,0)/hrs.length):null;$('#rideDetail').hidden=false;$('#rideDetail').innerHTML=`<div class="sectiontitle"><h3>${esc(r.name)}</h3><span class="badge">${r.points.length} titik GPS</span></div><div class="detailmetrics"><div>Jarak<b>${fmt(r.distance/1000,2)} <em>km</em></b></div><div>Waktu aktif<b>${clock(r.elapsed)}</b></div><div>Rata-rata<b>${fmt(r.elapsed?r.distance/r.elapsed*3600:0)} <em>km/j</em></b></div><div>Kecepatan maks.<b>${fmt(r.maxSpeed)} <em>km/j</em></b></div><div>Elevasi naik GPS<b>${r.elevationBase!=null?Math.round(r.ascent):'—'} <em>m</em></b></div><div>HR rata-rata<b>${avg??'—'} <em>bpm</em></b></div></div><p class="chartlabel">PROFIL ELEVASI · GPS dapat memiliki noise</p><svg class="detailchart" viewBox="0 0 800 110">${profileSVG(r.points)}</svg>${hrs.length>1?`<p class="chartlabel">HEART RATE · ${Math.min(...hrs.slice(0,100000))}–${Math.max(...hrs.slice(0,100000))} bpm</p><svg class="detailchart" viewBox="0 0 800 110">${profileSVG(hrs.filter((_,i)=>i%Math.max(1,Math.floor(hrs.length/500))===0).map(hr=>({alt:hr})),800,110,'#ff8c48').replaceAll(' m<',' bpm<')}</svg>`:''}<div class="buttonrow"><button class="outline" id="detailMap">Lihat jalur</button><button class="outline" id="renameRide">Ubah nama</button></div><div class="activity-downloads"><h4>Unduh rekaman</h4><div class="buttonrow"><button class="primary" id="detailExport">↓ GPX jalur</button><button class="outline" id="detailCSV">↓ CSV titik GPS</button><button class="outline" id="detailJSON">↓ JSON lengkap</button></div><p>GPX: jalur, waktu dan sensor yang tercatat pada titik GPS. CSV: speed, HR dan zona pada titik GPS. JSON: seluruh rekaman, sampel sensor, lap dan ringkasan aktivitas.</p></div><p class="muted">${r.laps.length} lap · Jarak dihitung dari titik GPS tersaring; elevasi merupakan perkiraan. Data HR dan waktu aktif hanya saat rekaman berjalan.</p>`;$('#detailMap').onclick=()=>{activeRoute={...r,id:null};$('#routeName').textContent=r.name;tab('ride');fitPoints(r.points);drawProfile();};$('#detailExport').onclick=()=>exportRide(r);$('#detailCSV').onclick=()=>{download(activityFilename(r,'csv'),activityCSV(r,settings.maxHR),'text/csv;charset=utf-8');toast('CSV titik GPS diunduh.');};$('#detailJSON').onclick=()=>{download(activityFilename(r,'json'),activityJSON(r));toast('Rekaman lengkap JSON diunduh.');};$('#renameRide').onclick=async()=>{const name=prompt('Nama aktivitas:',r.name);if(!name?.trim())return;const next=rides.map(x=>x.id===r.id?{...x,name:name.trim().slice(0,100)}:x);try{await commit([['rides',next]]);rides=next;renderHistory();showDetail(rides.find(x=>x.id===r.id));}catch(e){saveFailure(e);}};window.dispatchEvent(new CustomEvent('sotrack:detail',{detail:r}));$('#rideDetail').scrollIntoView({behavior:'smooth',block:'start'});}
$('#exportCSV').onclick=()=>{const quote=s=>'"'+String(s).replaceAll('"','""')+'"';let data='nama,tanggal,jarak_km,waktu_aktif_detik,rata_rata_kmj,maks_kmj,elevasi_naik_m\n'+rides.map(r=>[quote(r.name),new Date(r.start).toISOString(),fmt(r.distance/1000,3),Math.round(r.elapsed/1000),fmt(r.elapsed?r.distance/r.elapsed*3600:0,2),fmt(r.maxSpeed,2),Math.round(r.ascent)].join(',')).join('\n');download('sotrack-activities.csv','\ufeff'+data,'text/csv;charset=utf-8');};
