const sensorConfig={hr:{service:'heart_rate',characteristic:'heart_rate_measurement',label:'HR'},csc:{service:'cycling_speed_and_cadence',characteristic:'csc_measurement',label:'Cadence'},power:{service:'cycling_power',characteristic:'cycling_power_measurement',label:'Power'}};
async function connect(kind){if(!navigator.bluetooth){toast('Web Bluetooth tidak tersedia. Buka langsung di Chrome Android lewat HTTPS.');return;}const config=sensorConfig[kind],button=$(`[data-connect="${kind}"]`);button.disabled=true;let device;try{device=await navigator.bluetooth.requestDevice($('#showAllSensors').checked?{acceptAllDevices:true,optionalServices:[config.service,'battery_service']}:{filters:[{services:[config.service]}],optionalServices:['battery_service']});if(sensor[kind])disconnect(kind);const server=await device.gatt.connect(),service=await server.getPrimaryService(config.service),ch=await service.getCharacteristic(config.characteristic);let previous=null,previousAt=0;const handler=e=>{try{const v=e.target.value,now=Date.now();if(kind==='hr'){const x=heartRate(v);values.hr=x.contact&&x.bpm>0?x.bpm:null;seen.hr=now;if(ride?.running&&!ride.autoPaused&&values.hr&&ride.hrSamples.length<100000){ride.hrSamples.push({time:now,activeMs:elapsed(ride),hr:values.hr});}}else if(kind==='csc'){const curr=csc(v);values.cadence=previous&&now-previousAt<30000?Math.round(cadence(previous,curr)??0):null;seen.cadence=now;previous=curr;previousAt=now;}else{if(v.byteLength<4)throw Error('Paket power tidak lengkap');values.power=v.getInt16(2,true);seen.power=now;}updateLive();}catch(e){toast('Paket sensor tidak terbaca: '+e.message);}};ch.addEventListener('characteristicvaluechanged',handler);await ch.startNotifications();sensor[kind]={device,ch,handler};device.addEventListener('gattserverdisconnected',()=>{if(sensor[kind]?.device===device){sensor[kind]=null;if(kind==='hr')values.hr=null;else if(kind==='csc')values.cadence=null;else values.power=null;$(`#${kind}Device`).textContent='Koneksi terputus · hubungkan kembali';updateLive();toast(config.label+' terputus.');}});$(`#${kind}Device`).textContent='Terhubung · '+(device.name||config.label);try{const bs=await server.getPrimaryService('battery_service'),bc=await bs.getCharacteristic('battery_level'),v=await bc.readValue();$(`#${kind}Device`).textContent+=' · baterai '+v.getUint8(0)+'%';}catch{}toast(config.label+' terhubung.');}catch(e){if(device?.gatt.connected&&!sensor[kind])device.gatt.disconnect();toast(e.name==='NotFoundError'?'Pemilihan dibatalkan atau sensor tidak punya layanan yang diperlukan.':e.name==='SecurityError'?'Akses Bluetooth diblokir. Buka Site langsung di Chrome Android.':'Gagal menghubungkan: '+e.message);}finally{button.disabled=false;}}
function disconnect(kind){const s=sensor[kind];sensor[kind]=null;if(s){s.ch.removeEventListener('characteristicvaluechanged',s.handler);s.device.gatt.disconnect();}if(kind==='hr')values.hr=null;else if(kind==='csc')values.cadence=null;else values.power=null;$(`#${kind}Device`).textContent='Belum terhubung';updateLive();}$$('[data-connect]').forEach(b=>b.onclick=()=>connect(b.dataset.connect));$$('[data-disconnect]').forEach(b=>b.onclick=()=>disconnect(b.dataset.disconnect));$('#bluetoothSupport').textContent=navigator.bluetooth?'Browser ini menyediakan Web Bluetooth. Keberhasilan koneksi bergantung layanan sensor dan izin perangkat.':'Web Bluetooth tidak tersedia di browser ini. Gunakan Chrome Android; Chrome iPhone/iPad tidak mendukung koneksi ini.';
function fillSettings(){const f=$('#settingsForm');for(const [k,v]of Object.entries(settings)){const e=f.elements.namedItem(k);if(e){if(e.type==='checkbox')e.checked=v;else e.value=v;}}$('.avatar').textContent=settings.name.slice(0,2).toUpperCase();}
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const next={name:f.elements.name.value.trim(),weight:Number(f.elements.weight.value),maxHR:Number(f.elements.maxHR.value),target:Number(f.elements.target.value),drink:Number(f.elements.drink.value),autoPause:f.elements.autoPause.checked,keepAwake:f.elements.keepAwake.checked,sound:f.elements.sound.checked,theme:f.elements.theme.value,speedDisplay:f.elements.speedDisplay.value};try{await commit([['settings',next]]);settings=next;fillSettings();updateLive();if(!settings.keepAwake)releaseWake();else requestWake();window.dispatchEvent(new Event('sotrack:settings'));toast('Pengaturan tersimpan.');}catch(e){saveFailure(e);}};
async function storageInfo(){if(!navigator.storage)return;try{const estimate=await navigator.storage.estimate(),persisted=await navigator.storage.persisted();$('#storageInfo').textContent=`Pemakaian ±${fmt((estimate.usage||0)/1e6)} MB dari kuota browser ±${fmt((estimate.quota||0)/1e9)} GB. Penyimpanan persisten: ${persisted?'aktif':'belum aktif'}. Tetap buat backup.`;}catch{}}
$('#persist').onclick=async()=>{if(!navigator.storage?.persist){toast('Penyimpanan persisten tidak didukung.');return;}let ok;try{ok=await navigator.storage.persist();}catch{toast('Penyimpanan persisten belum tersedia.');return;}toast(ok?'Penyimpanan persisten aktif.':'Browser belum mengizinkan. Backup tetap bisa dipakai.');storageInfo();};
$('#backup').onclick=()=>{localStorage.setItem('sotrack-last-backup',String(Date.now()));download('sotrack-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'sotrack',version:1,created:Date.now(),settings,services:window.sotrack?.services,rides,routes,packs:packs.map(({features,...p})=>p),draft:ride,pro:window.sotrack?.proBackup?.()||null}));toast('Backup diunduh. Simpan file di tempat aman.');};
function validPoints(ps){return Array.isArray(ps)&&ps.length<=100000&&ps.every(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180&&(p.alt==null||Number.isFinite(p.alt)));}
function validateRecords(rs,isRide){if(!Array.isArray(rs)||rs.length>10000)throw Error('Daftar aktivitas/rute tidak valid.');const ids=new Set();for(const r of rs){if(typeof r.id!=='string'||!/^[-\w]{1,100}$/.test(r.id)||ids.has(r.id)||typeof r.name!=='string'||!validPoints(r.points))throw Error('Aktivitas/rute backup tidak valid.');ids.add(r.id);if(isRide&&(!Number.isFinite(r.start)||!Number.isFinite(r.elapsed)||r.elapsed<0||!Number.isFinite(r.distance)||r.distance<0||!Number.isFinite(r.maxSpeed)||!Number.isFinite(r.ascent)||!Array.isArray(r.laps)))throw Error('Statistik aktivitas backup tidak valid.');}}
$('#restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(ride)throw Error('Simpan atau buang aktivitas aktif sebelum memulihkan backup.');if(f.size>100e6)throw Error('Batas backup 100 MB.');const b=JSON.parse(await f.text());if(b.app!=='sotrack'||b.version!==1)throw Error('Ini bukan backup Sotrack versi 1.');validateRecords(b.rides,true);validateRecords(b.routes,false);if(!Array.isArray(b.packs)||b.packs.length>100)throw Error('Daftar peta tidak valid.');const nextPacks=b.packs.map(p=>normalizePack(p,p.name));const nextSettings={...settings,...b.settings};if(typeof nextSettings.name!=='string'||![nextSettings.weight,nextSettings.maxHR,nextSettings.target,nextSettings.drink].every(Number.isFinite)||nextSettings.weight<20||nextSettings.weight>250||nextSettings.maxHR<100||nextSettings.maxHR>240||nextSettings.target<1||nextSettings.target>1000||nextSettings.drink<0||nextSettings.drink>120)throw Error('Pengaturan backup tidak valid.');if(b.draft)validateRecords([b.draft],true);if(b.pro&&window.sotrack?.validatePro)window.sotrack.validatePro(b.pro);if(b.services){for(const key of ['photon','router','overpass'])serviceURL(b.services[key]);}if(!confirm('Pulihkan backup? Data aktivitas, rute, peta dan pengaturan saat ini akan diganti.'))return;const draft=b.draft?{...b.draft,running:false,autoPaused:false,nextBreak:true}:null;await commit([['rides',b.rides],['routes',b.routes],['packs',nextPacks],['settings',nextSettings],['pro',b.pro||window.sotrack.proBackup()],['services',b.services||window.sotrack.services],['draft',draft||undefined],['activeRoute',null]]);rides=b.rides;routes=b.routes;packs=nextPacks;settings=nextSettings;if(b.services){window.sotrack.services=b.services;window.dispatchEvent(new Event('sotrack:services'));}ride=draft;activeRoute=null;fillSettings();renderHistory();renderRoutes();updateLive();drawMap();drawProfile();renderLaps();storageInfo();window.dispatchEvent(new Event('sotrack:settings'));window.dispatchEvent(new Event('sotrack:packs'));if(b.pro&&window.sotrack?.restorePro)await window.sotrack.restorePro(b.pro,false);toast('Backup dipulihkan.');}catch(e){toast(e.message);}e.target.value='';};
$('#fullScreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Layar penuh tidak tersedia.');}};

