async function init(){try{db=await openDB();available=true;const results=await Promise.all(['settings','rides','routes','packs','draft','activeRoute'].map(read));settings={...settings,...results[0]};rides=results[1]||[];routes=results[2]||[];packs=(results[3]||[]).map(p=>({...p,features:packFeatures(p)}));ride=results[4]||null;activeRoute=routes.find(r=>r.id===results[5])||null;if(ride){ride.running=false;ride.autoPaused=false;ride.nextBreak=true;lastDrink=Math.floor(ride.elapsed/(Math.max(1,settings.drink)*60000));toast('Aktivitas belum selesai dipulihkan dalam keadaan jeda.');}$('#storageStatus').textContent='Data tersimpan lokal';fillSettings();renderRoutes();renderHistory();renderLaps();updateLive();drawProfile();if(activeRoute){$('#routeName').textContent=activeRoute.name;$('#routeHint').textContent=fmt(routeLength(activeRoute.points)/1000)+' km · tersimpan offline';}storageInfo();}catch(e){available=false;$('#storageStatus').textContent='Penyimpanan tidak tersedia';$('#start').disabled=true;toast('Browser tidak dapat membuka penyimpanan. Hindari mode privat dan coba muat ulang.');}tab(location.hash.startsWith('#shared=')?'ride':location.hash.slice(1)||'ride');window.dispatchEvent(new Event('sotrack:ready'));}
